section('migration: additive, idempotent, reversible');
$before = tbls($pdo); $sum = []; foreach ($before as $t) $sum[$t] = $pdo->query("CHECKSUM TABLE `$t`")->fetch(PDO::FETCH_NUM)[1];
run($pdo, "$root/database/phase7d_acquisition.sql"); run($pdo, "$root/database/phase7d_acquisition.sql"); $new = array_values(array_diff(tbls($pdo), $before)); sort($new); ok($new === ['crm_prospect_profile', 'crm_prospect_status_history', 'crm_prospect_suppressions'], 'adds exactly three tables');
$same = true; foreach ($before as $t) if ($pdo->query("CHECKSUM TABLE `$t`")->fetch(PDO::FETCH_NUM)[1] !== $sum[$t]) $same = false; ok($same, 'no existing table changed');
run($pdo, "$root/database/phase7d_rollback.sql"); ok(array_values(array_diff(tbls($pdo), $before)) === [] && $pdo->query('SELECT COUNT(*) FROM crm_prospects')->fetchColumn() == 1, 'rollback removes only the new tables; prospects stay'); run($pdo, "$root/database/phase7d_acquisition.sql"); ok(crm_acq_ready($pdo), 're-applies after rollback');

